# Type Hints (Annotations) 📋

Optional type information for better code clarity.

## Basic Type Hints

```python
def greet(name: str) -> str:
    return f"Hello, {name}!"

def add(a: int, b: int) -> int:
    return a + b

def is_even(n: int) -> bool:
    return n % 2 == 0
```

## Complex Types

```python
from typing import List, Dict, Optional, Tuple, Union

def get_names() -> List[str]:
    return ["Alice", "Bob"]

def get_scores() -> Dict[str, int]:
    return {"Alice": 95, "Bob": 87}

def find_user(id: int) -> Optional[str]:
    # Returns str or None
    return None

def get_point() -> Tuple[int, int]:
    return (10, 20)

def process(value: Union[int, str]) -> str:
    return str(value)
```

## Python 3.10+ Simplified Syntax

```python
def find_user(id: int) -> str | None:
    return None

def process(value: int | str) -> str:
    return str(value)
```

> 💡 **Note:** Type hints don't enforce types at runtime - they're for documentation and IDE support. Use `mypy` for static type checking!

# Real-World Decorators 🌟

## Timer Decorator

```python
import time

def timer(func):
    def wrapper(*args, **kwargs):
        start = time.time()
        result = func(*args, **kwargs)
        end = time.time()
        print(f"{func.__name__} took {end-start:.4f}s")
        return result
    return wrapper

@timer
def slow_function():
    time.sleep(1)
    return "Done!"

slow_function()  # slow_function took 1.0012s
```

## Memoization (Caching)

```python
def memoize(func):
    cache = {}
    def wrapper(*args):
        if args not in cache:
            cache[args] = func(*args)
        return cache[args]
    return wrapper

@memoize
def fibonacci(n):
    if n < 2:
        return n
    return fibonacci(n-1) + fibonacci(n-2)

print(fibonacci(100))  # Instant!
```

## Using functools.wraps

```python
from functools import wraps

def my_decorator(func):
    @wraps(func)  # Preserves function metadata
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapper
```

> 💡 **Built-in Decorators:** Python has useful built-in decorators like `@property`, `@staticmethod`, `@classmethod`!

# Built-in Decorators 🏗️

## @staticmethod

```python
class Math:
    @staticmethod
    def add(a, b):
        return a + b

# No self or cls needed
print(Math.add(3, 5))  # 8
```

## @classmethod

```python
class Person:
    count = 0

    def __init__(self, name):
        self.name = name
        Person.count += 1

    @classmethod
    def get_count(cls):
        return cls.count

    @classmethod
    def from_string(cls, data):
        name = data.split(",")[0]
        return cls(name)

p1 = Person("Alice")
p2 = Person.from_string("Bob,25")
print(Person.get_count())  # 2
```

## @property

```python
class Circle:
    def __init__(self, radius):
        self._radius = radius

    @property
    def radius(self):
        return self._radius

    @radius.setter
    def radius(self, value):
        if value < 0:
            raise ValueError("Radius can't be negative")
        self._radius = value

    @property
    def area(self):
        return 3.14159 * self._radius ** 2

c = Circle(5)
print(c.area)   # 78.54 (computed property)
c.radius = 10   # Uses setter
```
